CREATE TABLE categorias (id SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE, descripcion TEXT DEFAULT 'Sin descripción registrada');
CREATE TABLE proveedores (id_proveedor SERIAL PRIMARY KEY, ruc VARCHAR(20) UNIQUE NOT NULL, razon_social VARCHAR(255) NOT NULL, nombre_comercial VARCHAR(255), telefono VARCHAR(30), correo VARCHAR(100), direccion TEXT, ciudad VARCHAR(100), estado BOOLEAN DEFAULT TRUE);
CREATE TABLE imagenes (id SERIAL PRIMARY KEY, url TEXT NOT NULL, public_id TEXT);
CREATE TABLE usuarios (id SERIAL PRIMARY KEY, nombre_completo VARCHAR(255) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, rol VARCHAR(50) NOT NULL CHECK (rol IN ('ADMIN','CAJERO','ALMACENERO')), activo BOOLEAN DEFAULT TRUE, genero VARCHAR(30), imagen_id INTEGER REFERENCES imagenes(id), fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE productos (id SERIAL PRIMARY KEY, nombre VARCHAR(255) NOT NULL, descripcion TEXT DEFAULT 'Sin descripción', precio DECIMAL(10,2) NOT NULL CHECK(precio > 0), stock_actual INTEGER NOT NULL DEFAULT 0 CHECK(stock_actual >= 0), categoria_id INTEGER REFERENCES categorias(id) ON DELETE SET NULL, id_proveedor INTEGER REFERENCES proveedores(id_proveedor) ON DELETE SET NULL, activo BOOLEAN DEFAULT TRUE, etiquetas VARCHAR(50)[], imagen_url TEXT, fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clientes (id SERIAL PRIMARY KEY, nombre VARCHAR(255) NOT NULL, documento VARCHAR(20) UNIQUE NOT NULL, email VARCHAR(100), activo BOOLEAN DEFAULT TRUE, telefonos_secundarios VARCHAR(15)[]);
CREATE TABLE ventas (id SERIAL PRIMARY KEY, cliente_id INTEGER REFERENCES clientes(id), usuario_id INTEGER REFERENCES usuarios(id), total DECIMAL(10,2) NOT NULL CHECK(total > 0), fecha_venta TIMESTAMP DEFAULT CURRENT_TIMESTAMP, metodo_pago VARCHAR(50) NOT NULL DEFAULT 'EFECTIVO' CHECK(metodo_pago IN ('EFECTIVO','TARJETA','YAPE','PLIN','TRANSFERENCIA')), estado VARCHAR(20) NOT NULL DEFAULT 'COMPLETADO');
CREATE TABLE detalle_ventas (id SERIAL PRIMARY KEY, venta_id INTEGER REFERENCES ventas(id) ON DELETE CASCADE, producto_id INTEGER REFERENCES productos(id), cantidad INTEGER NOT NULL CHECK(cantidad > 0), precio_unitario DECIMAL(10,2) NOT NULL CHECK(precio_unitario > 0));
CREATE TABLE auditoria_precios (id SERIAL PRIMARY KEY, producto_id INTEGER REFERENCES productos(id) ON DELETE CASCADE, precio_anterior DECIMAL(10,2) NOT NULL, precio_nuevo DECIMAL(10,2) NOT NULL, fecha_cambio TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE movimientos_inventario (id SERIAL PRIMARY KEY, producto_id INTEGER REFERENCES productos(id) ON DELETE CASCADE, usuario_id INTEGER REFERENCES usuarios(id), tipo_movimiento VARCHAR(20) NOT NULL CHECK(tipo_movimiento IN ('INGRESO','SALIDA','AJUSTE')), cantidad INTEGER NOT NULL CHECK(cantidad > 0), motivo VARCHAR(255) NOT NULL, fecha_movimiento TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_productos_categoria ON productos(categoria_id);
CREATE INDEX idx_ventas_fecha ON ventas(fecha_venta);
CREATE INDEX idx_movimientos_producto ON movimientos_inventario(producto_id);
CREATE FUNCTION registrar_auditoria_precio() RETURNS TRIGGER AS $$ BEGIN IF NEW.precio <> OLD.precio THEN INSERT INTO auditoria_precios (producto_id,precio_anterior,precio_nuevo) VALUES (OLD.id,OLD.precio,NEW.precio); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_auditoria_precio AFTER UPDATE ON productos FOR EACH ROW EXECUTE FUNCTION registrar_auditoria_precio();
